#pragma once
namespace orders {
inline void reporting(crow::SimpleApp &app){
    {Db d(path);d.exec("CREATE TABLE IF NOT EXISTS business_expenses(id TEXT PRIMARY KEY,stall_id INTEGER NOT NULL,kind TEXT NOT NULL,source TEXT NOT NULL,amount INTEGER NOT NULL,reference TEXT NOT NULL,created INTEGER NOT NULL,UNIQUE(stall_id,reference)); CREATE TRIGGER IF NOT EXISTS expenses_no_update BEFORE UPDATE ON business_expenses BEGIN SELECT RAISE(ABORT,'immutable expense'); END; CREATE TRIGGER IF NOT EXISTS expenses_no_delete BEFORE DELETE ON business_expenses BEGIN SELECT RAISE(ABORT,'immutable expense'); END;");}
    CROW_ROUTE(app,"/api/business-expenses").methods("GET"_method,"POST"_method)([](const crow::request &r){return handle([&]{auto who=owner(r);auto sid=who["stall_id"].i();Db d(path);
        if(r.method!=crow::HTTPMethod::Post){Stmt s(d,"SELECT id,kind,source,amount,reference FROM business_expenses WHERE stall_id=? ORDER BY created DESC,rowid DESC LIMIT 100");s.bind(1,sid);Json out;out["entries"]=Json::list();int i=0;while(s.row()){out["entries"][i]["id"]=s.str(0);out["entries"][i]["kind"]=s.str(1);out["entries"][i]["source"]=s.str(2);out["entries"][i]["amount_paise"]=s.num(3);out["entries"][i++]["reference"]=s.str(4);}return json(200,std::move(out));}
        auto j=body(r);auto kind=text(j,"kind",20),source=text(j,"source",100),reference=text(j,"reference",120);auto amount=integer(j,"amount_paise",1,100000000);require(kind=="MARKETING"||kind=="PROCESSING",400,"Record marketing spend or processing fees");Transaction tx(d);Stmt prior(d,"SELECT id,kind,source,amount FROM business_expenses WHERE stall_id=? AND reference=?");prior.bind(1,sid).bind(2,reference);Json out;if(prior.row()){require(prior.str(1)==kind&&prior.str(2)==source&&prior.num(3)==amount,409,"Expense reference already used for different details");out["id"]=prior.str(0);}else{auto id=token();Stmt s(d,"INSERT INTO business_expenses VALUES(?,?,?,?,?,?,?)");s.bind(1,id).bind(2,sid).bind(3,kind).bind(4,source).bind(5,amount).bind(6,reference).bind(7,now()).row();audit(d,"EXPENSE_RECORDED",id,"owner:"+std::to_string(who["owner_id"].i()),reference);out["id"]=id;}tx.commit();return json(200,std::move(out));});});
    CROW_ROUTE(app,"/api/business-expenses/<string>/reverse").methods("POST"_method)([](const crow::request &r,std::string id){return handle([&]{auto who=owner(r);auto sid=who["stall_id"].i();auto j=body(r);auto reason=text(j,"reason",300);Db d(path);Transaction tx(d);Stmt original(d,"SELECT kind,source,amount FROM business_expenses WHERE id=? AND stall_id=?");original.bind(1,id).bind(2,sid);require(original.row()&&original.num(2)>0,404,"Original expense missing");auto reversal="reversal_"+id;Stmt s(d,"INSERT OR IGNORE INTO business_expenses VALUES(?,?,?,?,?,?,?)");s.bind(1,reversal).bind(2,sid).bind(3,original.str(0)).bind(4,original.str(1)).bind(5,-original.num(2)).bind(6,reversal).bind(7,now()).row();if(sqlite3_changes(d.p))audit(d,"EXPENSE_REVERSED",id,"owner:"+std::to_string(who["owner_id"].i()),reason);tx.commit();Json out;out["id"]=reversal;return json(200,std::move(out));});});
}
}
